begin;
create extension if not exists pgcrypto;
create table public.universities(id uuid primary key default gen_random_uuid(), name text not null unique);
create table public.profiles(id uuid primary key references auth.users on delete cascade, first_name text not null default '', university text not null default '', program text not null default '', year int not null default 1 check(year between 1 and 8), week_a_start date not null default '2026-09-07');
create table public.groups(id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles, name text not null check(length(name) between 1 and 80), invite_code text not null unique default upper(encode(gen_random_bytes(6),'hex')), created_at timestamptz not null default now());
create table public.group_members(id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups on delete cascade,user_id uuid not null references public.profiles on delete cascade,role text not null default 'member' check(role in ('owner','admin','member')),unique(group_id,user_id));
create function public.is_member(g uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from group_members where group_id=g and user_id=auth.uid())$$;
create function public.is_admin(g uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from group_members where group_id=g and user_id=auth.uid() and role in ('owner','admin'))$$;
create function public.can_read(o uuid,g uuid) returns boolean language sql stable as $$select (g is null and o=auth.uid()) or (g is not null and public.is_member(g))$$;
create table public.subjects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles,group_id uuid references public.groups on delete cascade,name text not null,teacher text not null default '',classroom text not null default '',color text not null default '#6264d9',description text not null default '',created_at timestamptz not null default now());
create table public.classes(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles,group_id uuid references public.groups on delete cascade,subject_id uuid references public.subjects on delete set null,title text not null,teacher text default '',classroom text default '',start_time time not null,end_time time not null,weekday int not null check(weekday between 0 and 6),date date not null,repeat text not null default 'every' check(repeat in ('every','A','B','once')),type text not null check(type in ('Lecture','Seminar','Lab')),body text default '',created_at timestamptz not null default now(),check(end_time>start_time));
create table public.assignments(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles,group_id uuid references public.groups on delete cascade,subject_id uuid references public.subjects on delete set null,title text not null,description text default '',deadline date not null,priority text not null default 'Medium' check(priority in ('Low','Medium','High')),status text not null default 'Not started' check(status in ('Not started','In progress','Done')),created_at timestamptz not null default now());
create table public.assignment_members(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments on delete cascade,user_id uuid not null references public.profiles on delete cascade,status text not null check(status in ('Not started','In progress','Done')),unique(assignment_id,user_id));
create table public.notes(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles,group_id uuid references public.groups on delete cascade,subject_id uuid references public.subjects on delete set null,title text not null,body text not null default '',created_at timestamptz not null default now());
create table public.files(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles,group_id uuid references public.groups on delete cascade,subject_id uuid references public.subjects on delete set null,assignment_id uuid references public.assignments on delete set null,name text not null,path text not null unique,mime_type text not null,size bigint not null check(size between 0 and 20971520),created_at timestamptz not null default now());
create table public.announcements(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles,group_id uuid not null references public.groups on delete cascade,title text not null,body text not null default '',created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,title text not null,body text default '',href text not null default '/',read boolean not null default false,created_at timestamptz not null default now());
create table public.activity_log(id uuid primary key default gen_random_uuid(),group_id uuid not null references public.groups on delete cascade,owner_id uuid references public.profiles on delete set null,title text not null,created_at timestamptz not null default now());
create table public.ai_usage(user_id uuid not null references public.profiles on delete cascade,day date not null default current_date,requests int not null default 0,primary key(user_id,day));
create function public.consume_ai_credit() returns boolean language plpgsql security definer set search_path=public as $$declare n int; begin if auth.uid() is null then return false;end if;insert into ai_usage(user_id,requests) values(auth.uid(),1) on conflict(user_id,day) do update set requests=ai_usage.requests+1 returning requests into n;return n<=30;end$$;
create function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id) values(new.id);return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_profile();
create function public.create_group(group_name text) returns uuid language plpgsql security definer set search_path=public as $$declare g uuid;begin if auth.uid() is null then raise exception 'Sign in first';end if;insert into groups(owner_id,name) values(auth.uid(),group_name) returning id into g;insert into group_members(group_id,user_id,role) values(g,auth.uid(),'owner');return g;end$$;
create function public.join_group(code text) returns uuid language plpgsql security definer set search_path=public as $$declare g uuid;begin if auth.uid() is null then raise exception 'Sign in first';end if;select id into g from groups where invite_code=upper(trim(code));if g is null then raise exception 'Invite code not found';end if;insert into group_members(group_id,user_id) values(g,auth.uid()) on conflict do nothing;return g;end$$;
create function public.manage_member(member_id uuid,new_role text) returns void language plpgsql security definer set search_path=public as $$declare m group_members;begin select * into m from group_members where id=member_id;if not exists(select 1 from groups where id=m.group_id and owner_id=auth.uid()) or m.role='owner' then raise exception 'Only the owner can manage other members';end if;if new_role='remove' then delete from group_members where id=member_id;elsif new_role in ('admin','member') then update group_members set role=new_role where id=member_id;else raise exception 'Invalid role';end if;end$$;
-- Prevent references to a private subject or assignment from leaking into shared content.
create function public.validate_scope() returns trigger language plpgsql security definer set search_path=public as $$declare s subjects; a assignments;begin if TG_OP='UPDATE' and (new.owner_id is distinct from old.owner_id or new.group_id is distinct from old.group_id) then raise exception 'Ownership and visibility cannot be changed';end if;if new.subject_id is not null then select * into s from subjects where id=new.subject_id;if not can_read(s.owner_id,s.group_id) or s.group_id is distinct from new.group_id then raise exception 'Subject must have the same visibility';end if;end if;if TG_TABLE_NAME='files' then if new.assignment_id is not null then select * into a from assignments where id=new.assignment_id;if not can_read(a.owner_id,a.group_id) or a.group_id is distinct from new.group_id then raise exception 'Assignment must have the same visibility';end if;end if; if new.path not like (case when new.group_id is null then 'private/'||new.owner_id::text else 'group/'||new.group_id::text end)||'/%' then raise exception 'Invalid storage path';end if;end if;return new;end$$;
do $$declare t text;begin foreach t in array array['classes','assignments','notes','files'] loop execute format('create trigger scope_guard before insert or update on public.%I for each row execute function public.validate_scope()',t);end loop;end$$;
-- Subject scope is immutable, including when no dependent records exist.
create function public.immutable_scope() returns trigger language plpgsql as $$begin if new.owner_id is distinct from old.owner_id or new.group_id is distinct from old.group_id then raise exception 'Ownership and visibility cannot be changed';end if;return new;end$$;
create trigger subject_scope before update on public.subjects for each row execute function public.immutable_scope();
create trigger announcement_scope before update on public.announcements for each row execute function public.immutable_scope();
alter table public.profiles enable row level security;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or exists(select 1 from group_members a join group_members b on a.group_id=b.group_id where a.user_id=auth.uid() and b.user_id=profiles.id));
create policy profile_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
alter table public.groups enable row level security;
create policy groups_read on public.groups for select to authenticated using(is_member(id));
create policy groups_update on public.groups for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
alter table public.group_members enable row level security;
create policy members_read on public.group_members for select to authenticated using(is_member(group_id));
do $$declare t text;begin foreach t in array array['subjects','classes','assignments','notes','files','announcements'] loop
execute format('alter table public.%I enable row level security',t);
execute format('create index on public.%I(group_id)',t);execute format('create index on public.%I(owner_id)',t);
execute format('create policy scoped_read on public.%I for select to authenticated using(public.can_read(owner_id,group_id))',t);
execute format('create policy scoped_insert on public.%I for insert to authenticated with check(owner_id=auth.uid() and (group_id is null or public.%s(group_id)))',t,case when t in ('classes','announcements','subjects') then 'is_admin' else 'is_member' end);
execute format('create policy scoped_update on public.%I for update to authenticated using((group_id is null and owner_id=auth.uid()) or (group_id is not null and public.%s(group_id) and (owner_id=auth.uid() or public.is_admin(group_id)))) with check(public.can_read(owner_id,group_id))',t,case when t in ('classes','announcements','subjects') then 'is_admin' else 'is_member' end);
execute format('create policy scoped_delete on public.%I for delete to authenticated using((group_id is null and owner_id=auth.uid()) or (group_id is not null and public.%s(group_id) and (owner_id=auth.uid() or public.is_admin(group_id))))',t,case when t in ('classes','announcements','subjects') then 'is_admin' else 'is_member' end);
end loop;end$$;
alter table public.assignment_members enable row level security;
create policy progress_own on public.assignment_members for all to authenticated using(user_id=auth.uid() and exists(select 1 from assignments a where a.id=assignment_id)) with check(user_id=auth.uid() and exists(select 1 from assignments a where a.id=assignment_id));
alter table public.notifications enable row level security;
create policy notification_read on public.notifications for select to authenticated using(user_id=auth.uid());
create policy notification_update on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table public.activity_log enable row level security;
create policy activity_read on public.activity_log for select to authenticated using(is_member(group_id));
alter table public.universities enable row level security;
create policy university_read on public.universities for select to authenticated using(true);
alter table public.ai_usage enable row level security;
create index on public.assignments(deadline);
create index on public.notifications(user_id,read);
create index on public.group_members(user_id);
create function public.record_activity() returns trigger language plpgsql security definer set search_path=public as $$declare label text;begin if new.group_id is not null then label:=coalesce((select first_name from profiles where id=auth.uid()),'A student')||case when TG_OP='INSERT' then ' added ' else ' updated ' end||coalesce(to_jsonb(new)->>'name',to_jsonb(new)->>'title');insert into activity_log(group_id,owner_id,title) values(new.group_id,auth.uid(),label);insert into notifications(user_id,title,href) select user_id,label,case TG_TABLE_NAME when 'assignments' then '/tasks' when 'classes' then '/schedule' when 'files' then '/files' else '/group' end from group_members where group_id=new.group_id and user_id<>auth.uid();end if;return new;end$$;
do $$declare t text;begin foreach t in array array['assignments','classes','files','announcements'] loop execute format('create trigger activity after insert or update on public.%I for each row execute function public.record_activity()',t);end loop;end$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('materials','materials',false,20971520,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create function public.storage_scope(p text) returns boolean language plpgsql stable set search_path=public as $$begin return (split_part(p,'/',1)='private' and split_part(p,'/',2)=auth.uid()::text) or (split_part(p,'/',1)='group' and public.is_member(split_part(p,'/',2)::uuid));exception when invalid_text_representation then return false;end$$;
create policy materials_read on storage.objects for select to authenticated using(bucket_id='materials' and public.storage_scope(name));
create policy materials_insert on storage.objects for insert to authenticated with check(bucket_id='materials' and public.storage_scope(name));
create policy materials_delete on storage.objects for delete to authenticated using(bucket_id='materials' and public.storage_scope(name) and (owner_id=auth.uid()::text or (split_part(name,'/',1)='group' and public.is_admin(split_part(name,'/',2)::uuid))));
-- Deadline notifications can be called on login; no privileged client credentials needed.
create function public.refresh_deadlines() returns void language plpgsql security definer set search_path=public as $$begin insert into notifications(user_id,title,body,href) select auth.uid(),'Assignment due tomorrow',a.title,'/tasks' from assignments a where can_read(a.owner_id,a.group_id) and deadline=current_date+1 and not exists(select 1 from assignment_members m where m.assignment_id=a.id and m.user_id=auth.uid() and m.status='Done') and not exists(select 1 from notifications n where n.user_id=auth.uid() and n.title='Assignment due tomorrow' and n.body=a.title and n.created_at::date=current_date);end$$;
revoke execute on all functions in schema public from public,anon;
grant execute on all functions in schema public to authenticated;
alter publication supabase_realtime add table public.assignments,public.classes,public.files,public.announcements,public.notifications,public.activity_log,public.group_members,public.subjects,public.notes,public.groups,public.assignment_members;
commit;
